internal sealed class SixSupportLaplacianLowRootDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/SpectralGraph/SixSupportLaplacianLowRoot.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/GraphInvariants/idealintersection2026sixsupport");
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The six-support weighted quotient, its symmetric representative, sharp balanced threshold, global endpoint spectrum, fixed-real-gap endpoint application and integer finiteness.",
        H("Six-support quotient, balanced threshold, endpoint applications and integer finiteness"), Blocks(
            Paragraph(Text("The support order for C is 1,2,3,12,13,23. The public source is paper/core/body.tex in the-omega-institute/ideal-intersection-laplacian at commit b93becea662a746badeadba42fdc3d3eb3db9382. Its quotient and energy occur on lines 574–600 and 774–784; its balanced sharpness proposition occurs on lines 114–145. The matrix model and balanced statement are attributed to that source. The Lean proofs and this exposition are independently authored; no novelty or graph-integrality classification is asserted.")),
            Node("quotient", "The literal nonsymmetric quotient", "quotient", ABC(Eq(Q(), QuotientMatrix())),
                "Rows and columns have the stated original support order. Multiplying on the left by diag(a,b,c,ab,ac,bc) makes the matrix symmetric.", DescribeRole.Definition),
            Node("weights", "Support weights", "weights", ABC(Eq(W(), Vector(V("a"),V("b"),V("c"),Mul(V("a"),V("b")),Mul(V("a"),V("c")),Mul(V("b"),V("c"))))),
                "The final three weights are the pair-support class sizes.", DescribeRole.Definition),
            Node("permutation", "Paired-coordinate reversal", "supportPermutation", Eq(Call("supportPermutation"),Call("permutation",Vector(D(0),D(1),D(2),D(5),D(4),D(3)))),
                "This involution changes the support order to 1,2,3,23,13,12.", DescribeRole.Definition),
            Node("roots", "Square-root diagonal", "rootWeights", ABC(Eq(Roots(),Vector(Sqrt(V("a")),Sqrt(V("b")),Sqrt(V("c")),Mul(Sqrt(V("b")),Sqrt(V("c"))),Mul(Sqrt(V("a")),Sqrt(V("c"))),Mul(Sqrt(V("a")),Sqrt(V("b")))))),
                "All six entries are positive when a,b,c are positive. Their squares are the reordered support weights.", DescribeRole.Definition),
            Node("symmetric", "The symmetric representative", "symmetric", ABC(Eq(S(), SymmetricMatrix())),
                "The paired diagonal is a,b,c; each singleton is coupled to its complementary pair by minus sqrt(a)sqrt(b)sqrt(c), equal to minus sqrt(abc) at positive parameters.", DescribeRole.Definition),
            Node("transport", "Return to the actual quotient", "toQuotientVector", ABC(All("z",Vec(),All("i",FinSix(),Eq(App(Call("toQuotientVector",V("a"),V("b"),V("c"),V("z")),V("i")),
                Div(App(V("z"),PermInverse(V("i"))),App(Roots(),PermInverse(V("i")))))))),
                "The inverse coordinate permutation and positive inverse diagonal preserve nonzero vectors and transport the same real eigenvalue to C.", DescribeRole.Definition),
            Node("geometry", "Weighted energy, kernel and similarity", "quotient_geometry", ABC(PositiveABC(Geometry())),
                "The energy is a sum over the singleton triangle and the three complementary-pair edges. Positivity forces all six coordinates of a zero-kernel vector to agree. The symmetric form is also a sum of six real squares. The exact similarity and eigenvector transport concern C itself.", DescribeRole.Theorem),
            Node("small-second", "A negative plane at a small second weight", "small_second_negative_plane", SmallSecond(),
                "For positive a,b,c with a at most b and b at most three, put p=sqrt(a)sqrt(b)sqrt(c), A=b+c+bc, B=a+c+ac, and t=(A+B+sqrt(a)sqrt(b)+1)/p. The plane consists of (u,v,0,tu,tv,0) in reordered coordinates. Its first two coordinates make the parametrization injective. The two paired diagonal contributions are nonpositive, and the singleton cross term is controlled by the square of u+v. The quadratic form of the symmetric matrix minus three times the identity is strictly negative on every nonzero vector of this plane. No division by a−3 or b−3 occurs, so their equality boundaries are included.", DescribeRole.Theorem, AssessedProvenance.FromRepo(Source)),
            Node("positive-real", "Low eigenvalue for every positive real triple", "positive_real_low_eigenvalue", ABC(Imp(Lt(D(0),V("a")),Imp(Le(V("a"),V("b")),Imp(Le(V("b"),V("c")),Ex("e",Real(),And(Lt(D(0),V("e")),Lt(V("e"),D(3)),Ex("z",Vec(),And(Ne(V("z"),D(0)),Eq(MulVec(Q(),V("z")),Smul(V("e"),V("z"))))))))))),
                "For balanced weights at least one, the proof directly consumes the balanced threshold theorem and its actual quotient eigenpair. For the remaining triples it uses three explicit negative planes for the symmetric matrix shifted by three. When b is at most three, the small-second plane applies. When a is at most three but b is greater than three, the paired b and c coordinates are eliminated and the positive singleton diagonal completes a square; this includes a equal to three. When a is greater than three, the source comparison matrix is nonpositive on vectors (x,sqrt(b)y,sqrt(c)y): its form is minus (b+c)/2 times (x+2sqrt(a)y) squared minus 3/(2a) times (2bc-a(b+c))x squared. Ordering makes the latter coefficient nonnegative, including equal parameters. The positive Schur correction makes the lifted plane strictly negative. This explicit plane is a repository synthesis of the source geometry. A vector in each plane is chosen orthogonal to the simple zero kernel. The real Hermitian spectral expansion then forces a positive eigenvalue below three. The proved similarity transports its nonzero real eigenvector to the actual nonsymmetric quotient C. No ordered-eigenvalue convention or unproved inertia count is assumed.", DescribeRole.Theorem),
            Node("low", "The balanced smaller root", "balancedLow", All("m",Real(),Eq(Low(V("m")),LowFormula(V("m")))),
                "The discriminant is strictly positive for m at least one.", DescribeRole.Definition),
            Node("balanced", "Balanced smallest positive eigenvalue and sharp threshold", "balanced_sharp_threshold", Balanced(),
                "The factorization gives zero, m squared plus m, and the two quadratic roots, each quadratic root counted twice. For q_m(x)=x squared minus (m squared plus 4m)x plus 3m squared, q_m(0)=3m squared is positive, q_m(m)=minus m cubed is negative, and q_m(3)=9−12m is negative when m is at least one. The smaller quadratic root lies between zero and m; the larger root exceeds m squared plus m. A nonzero real symmetric eigenvector is constructed and transported by the proved similarity to C. Rationalization gives the strict lower bound 3m/(m+4), while the upper bound is three. The lower bound tends to three, so squeezing proves the real limit and the positive-integer subsequence limit. For every K below three there is a positive integer m whose smallest positive quotient eigenvalue exceeds K; every other positive real quotient eigenvalue then also exceeds K. Thus no constant smaller than three bounds the smallest positive quotient eigenvalues uniformly. The positive-real theorem supplies the same uniform bound for unequal ordered weights; the integer consequence follows by specializing its parameters.", DescribeRole.Theorem),
            Paragraph(Text("Global separation and endpoint-one isolation. The following complete real-parameter application is attributed to thm:endpoint-one-spectrum and its proof through sharpness in paper/sections/endpoint-one-spectrum.tex of the public source at b93becea662a746badeadba42fdc3d3eb3db9382. The argument below is independently authored and uses the existing quotient geometry, real inertia and characteristic-polynomial suppliers. It is application exposition; the existing Describe statements retain their displayed geometry, low-root and balanced scope and do not certify this additional result. No fresh kernel acceptance of this application is asserted.")),
            Paragraph(Text("Statement on the actual spectrum. For every real a,b,c with 2 ≤ a ≤ b ≤ c, take C = SixSupportLaplacianLowRoot.quotient a b c in support order 1,2,3,12,13,23, with weights a,b,c,ab,ac,bc. Write χ_C(X) for its characteristic polynomial and h_C(X) = χ_C(X)/X for exact polynomial division. Thus χ_C(X) = X h_C(X), and h_C(x) = det(xI−C)/x when x ≠ 0. Let λ₁,…,λ₆ be its ascending real characteristic roots, counted with algebraic multiplicity, and put s = a+b+c. Then")),
            Paragraph(Text("0 = λ₁ < λ₂ ≤ λ₃ < a+b < s ≤ λ₄ ≤ λ₅ ≤ λ₆, with λ₄ = s if and only if (a,b,c) = (2,2,2).")),
            Paragraph(Text("At that boundary χ_C(X) = X(X−6)(X²−12X+12)². If h_C(1) = 0, then b+c ≥ 2a²−2a+1, with equality if and only if b = a and c = (a−1)(2a−1). If also a > κ = 2+sqrt(3), one is a simple root and the smallest positive quotient root. The exact monic quartic R_C(X) = h_C(X)/(X−1) has ascending roots μ₁,…,μ₄, with algebraic multiplicity, satisfying a < μ₁ < min{c,a+b} and s < μ₂ ≤ μ₃ ≤ μ₄. In particular every residual root exceeds a.")),
            Paragraph(Text("The cutoff is sharp on the entire ordered real endpoint-one family b = a, c = (a−1)(2a−1), a ≥ 2: h_C(1) = 0 there; at a = κ its smallest residual root equals a; and for every real 2 ≤ a < κ at least one residual root lies below a. The assertion below the cutoff removes only one occurrence of the root one and makes no assumption that one is simple in that range.")),
            Paragraph(Text("Actual carrier and multiplicities. All three parameters are positive, so quotient_geometry supplies the constant one-dimensional kernel of C and positive semidefiniteness of the existing S = symmetric a b c. In stored coordinates S has support order 1,2,3,23,13,12. With p = supportPermutation = [0,1,2,5,4,3] and D = diag(rootWeights a b c), that same theorem gives S = D C[p,p] D⁻¹. Every entry of D is positive. Reindexing by p and conjugating by this invertible diagonal preserve the entire characteristic polynomial, by Matrix.charpoly_reindex and charpoly_units_conj (or the equivalent intertwining form charpoly_eq_of_mul_eq_mul).")),
            Paragraph(Text("Use Matrix.IsHermitian.eigenvalues₀ for S and reverse its antitone Fin 6 enumeration: λᵢ is its entry at 6−i for 1 ≤ i ≤ 6. The pinned spectral theorem, charpoly_eq, roots_charpoly_eq_eigenvalues₀ and sort_roots_charpoly_eq_eigenvalues₀ give χ_C(X) = ∏ᵢ₌₁⁶(X−λᵢ) and χ_C.roots equal to the multiset of these six entries. Similarity transfers the one-dimensional constant kernel to S; Hermitian diagonalization and rank-nullity make zero occur exactly once. Positive semidefiniteness then gives λ₂,…,λ₆ > 0. Consequently h_C is monic of degree five with precisely those five positive roots, including their multiplicities. On h_C(1) = 0, exact division by X−1 defines a monic quartic R_C and removes exactly one occurrence of one from this multiset. These are the actual characteristic roots of C, rather than an assumed list of eigenvalues or a set that discards repetitions.")),
            Paragraph(Text("Real count bounds used in the proof. For a real t, let N(t) be the number of the six λᵢ strictly below t, counted with multiplicity. In the same orthonormal eigenbasis, tI−S is diagonal with entries t−λᵢ, so its positive index is N(t); the positive index of S−tI counts λᵢ > t. RHLinalg.finrank_le_posIndex_of_posDefOn and posIndex_conj_le apply over ℝ to an actual positive subspace or coordinate compression. Their hypotheses require Hermitianity and the displayed form signs, without assuming distinct roots or strict parameter ordering. The spectral diagonalization and the existing real invertible-congruence inertia theorem identify these indices with the stated counts.")),
            Paragraph(Text("For an upper count, use the positive spectral subspace supplied by posIndex_eq_max_finrank_posDefOn. If a shifted form is nonpositive on a coordinate subspace E, its positive spectral subspace meets E only in zero: a nonzero intersection vector would have both a positive and a nonpositive form value. Submodule.finrank_add_finrank_le_of_disjoint therefore bounds the positive index by 6−dim(E). This also handles a zero diagonal entry and repeated parameters. Finally, if no root equals t, the six-factor characteristic product has sign (−1)^(6−N(t)) = (−1)^N(t). This parity conclusion will always be used together with a proved interval for N(t).")),
            Paragraph(Text("A division-free determinant identity. For an arbitrary real x, put A_a(x) = (x−a)(x−b−c−bc)−abc, A_b(x) = (x−b)(x−a−c−ac)−abc and A_c(x) = (x−c)(x−a−b−ab)−abc. The literal six-by-six quotient gives")),
            Paragraph(Text("χ_C(x) = A_a(x)A_b(x)A_c(x) − ab(x−a)(x−b)A_c(x) − ac(x−a)(x−c)A_b(x) − bc(x−b)(x−c)A_a(x) + 2abc(x−a)(x−b)(x−c).")),
            Paragraph(Text("To obtain this from Matrix.det_apply, group the fixed-point and transposition choices for each pendant pair support with its sole singleton neighbor. The grouped factors are the three A terms. A transposition between two singleton supports contributes the corresponding negative ab, ac or bc term, and the two orientations of their triangle give the final positive term. No other nonzero permutation cycle is possible. No division by x−a, x−b or x−c occurs, so this identity remains valid at each of those points and at repeated parameters. At x = 1 it is the same determinant identity used in the fixed-gap application below, with no gap or eventual-size hypothesis.")),
            Paragraph(Text("Three roots below a+b. Put t = a+b and ρ = sqrt(a)sqrt(b)sqrt(c), so ρ² = abc. In original support order 3,12,13,23, the principal block of S is [[ab+a+b,−ρ],[−ρ,c]] direct-sum (b) direct-sum (a); its selector in stored coordinates is [2,5,4,3]. The two-dimensional block has characteristic polynomial Q(x) = x²−(ab+a+b+c)x+c(a+b), and Q(t) = −ab t < 0. Its shifted form can also be read directly as")),
            Paragraph(Text("ab u²−2ρuv+(c−t)v² = ab(u−ρv/(ab))²−t v².")),
            Paragraph(Text("Since ab > 0 and t > 0, this invertible change of two coordinates gives one positive and one negative square. The two scalar shifts are b−t = −a and a−t = −b. Thus the four-dimensional block has exactly three eigenvalues below t, and its three negative directions give three positive directions for tI−S by the real inertia supplier. Hence N(a+b) ≥ 3, or λ₃ < a+b. Since c > 0, also a+b < s.")),
            Paragraph(Text("Two roots above s away from the boundary. On singleton supports 1,2, the principal block of S−sI is [[bc−a,−sqrt(a)sqrt(b)],[−sqrt(a)sqrt(b),ac−b]]. Its first pivot d = bc−a is at least a(a−1) > 0. Its determinant is cΔ, where Δ = abc−a²−b² = ab(c−b)+(a−1)(b−a)(b+a)+(a−2)a². All three summands are nonnegative. If Δ = 0, the last forces a = 2, the middle forces b = a, and the first forces c = b. Conversely Δ = 0 at (2,2,2). Off that point Δ > 0; multiplying this block's form by d completes it to (du−sqrt(a)sqrt(b)v)²+cΔv². The block is positive definite and the real inertia bound gives at least two λᵢ > s, so λ₅ > s.")),
            Paragraph(Text("The determinant fixes the remaining position. Set p = ab+ac+bc and r = abc, as actual functions of the same parameters. Substituting x = s in the division-free identity and using s > 0 yields h_C(s) = −rs V, where V = r(s+3)−sp = a²(bc−b−c)+b²(ac−a−c)+c²(ab−a−b). For example bc−b−c = (b−2)(c−1)+(c−2) ≥ 0, with equality exactly when b = c = 2; the other brackets have the same property. Since the square coefficients are positive, V vanishes exactly at the all-two triple. Away from that point χ_C(s) = −rs²V < 0 and no λᵢ equals s. The bounds just proved give 3 ≤ N(s) ≤ 4. Its determinant sign forces N(s) odd, hence N(s) = 3 and λ₄ > s.")),
            Paragraph(Text("At (a,b,c) = (2,2,2), apply the existing balanced_sharp_threshold at m = 2, whose hypothesis is only m ≥ 1. It gives χ_C(X) = X(X−6)(X²−12X+12)². The ascending root multiset is 0, 6−2sqrt(6), 6−2sqrt(6), 6, 6+2sqrt(6), 6+2sqrt(6). Here 0 < 6−2sqrt(6) < 4 and s = 6. This proves the entire global ordering, including all multiplicities, and both directions of λ₄ = s if and only if the triple is all two.")),
            Paragraph(Text("Endpoint comparison. Assume h_C(1) = 0. Keep q = b+c and z = bc tied to the ordered parameters, and put K = 4a²−2a+1 and Q = 2a²−2a+1. Expansion of the same literal determinant at x = 1 gives")),
            Paragraph(Text("h_C(1) = (q−K)z²−a(a−1)(q+2a−1)z+P_a(q), where P_a(q) = (a²−1)q³+(a³−a²−3a+3)q²−3(a−1)²q−(a−1)³.")),
            Paragraph(Text("Define E_a(q,z) to be this displayed expression, only as local notation. Let z₀ = a(q−a). Ordering gives z−z₀ = (b−a)(c−a) ≥ 0, q ≥ 2a and z₀ ≥ a² > 0. If q ≤ Q, then q−K ≤ −2a² < 0, and")),
            Paragraph(Text("E_a(q,z)−E_a(q,z₀) = (z−z₀)[(q−K)(z+z₀)−a(a−1)(q+2a−1)] ≤ 0.")),
            Paragraph(Text("The bracket is strictly negative, because z+z₀ > 0 and q+2a−1 > 0. Thus equality in this comparison occurs exactly when z = z₀. For t = q−a ≥ a, direct factorization gives E_a(q,z₀) = [(a−1)(2a−1)−t]B(a,t) = (Q−q)B(a,t), where B(a,t) = a³−2a²t²+a²t+a²+3at−3a+t²−2t+1.")),
            Paragraph(Text("Its sign follows from a complete positive decomposition. Write t = a+u with u ≥ 0. Then −B(a,a+u) = (2a²−1)u²+[(a−2)(4a²+7a+9)+20]u+(a−2)[2a³+a(2a−1)+3]+5. Each term is nonnegative for a ≥ 2, and the constant term is at least five. Hence B(a,t) < 0 on the whole real domain, including a = 2. If q < Q, the last factorization and comparison would give h_C(1) < 0, a contradiction. Therefore b+c ≥ Q.")),
            Paragraph(Text("If q = Q on the endpoint surface, E_a(q,z₀) = 0, so h_C(1) = 0 forces z = z₀. Then (b−a)(c−a) = 0 and a ≤ b ≤ c force b = a; consequently c = Q−a = (a−1)(2a−1). Conversely, for every real a ≥ 2, these parameters satisfy c−a = 2a(a−2)+1 ≥ 1 and hence are ordered. They have q = Q and z = z₀, so the same actual determinant factorization gives h_C(1) = 0 and equality. This proves the full equality iff without an independent cubic or a positivity assumption.")),
            Paragraph(Text("Isolation above the cutoff. Suppose additionally a > κ = 2+sqrt(3). Then a²−4a+1 = (a−2)²−3 > 0. The endpoint sum bound yields b+c−(a²+2a) ≥ a²−4a+1 > 0. Evaluating the actual determinant identity at x = a gives h_C(a) = −a²b²c²(a²+2a−b−c) > 0, and χ_C(a) = a h_C(a) > 0. Thus no λᵢ equals a.")),
            Paragraph(Text("In stored coordinates let E be the three-dimensional subspace with zero singleton coordinates. The form of aI−S on E is (a−a)u²+(a−b)v²+(a−c)w² ≤ 0. Its positive spectral subspace is disjoint from E, so the upper count mechanism gives N(a) ≤ 3, including all repeated-parameter cases. Zero and at least one occurrence of one lie below a, hence N(a) ≥ 2. The positive determinant forces even N(a), so N(a) = 2. Since zero is already simple, there is exactly one occurrence of one and no other positive root below a. Thus λ₂ = 1 is simple and smallest positive, while λ₃,…,λ₆ > a.")),
            Paragraph(Text("For the upper residual endpoint, S−cI has form (a−c)u²+(b−c)v² on that same pair subspace, so at most three full roots exceed c. Equivalently λ₃ ≤ c. Actual determinant evaluation gives h_C(c) = −a²b²c²(c²+2c−a−b) < 0, since a+b ≤ 2c and c > 0. No characteristic root equals c, so λ₃ < c. The global gap gives λ₃ < a+b and λ₄ > s; its exceptional all-two case is excluded here. Exact division now identifies the ordered multiset of R_C with (λ₃,λ₄,λ₅,λ₆), proving a < μ₁ < min{c,a+b} and s < μ₂ ≤ μ₃ ≤ μ₄.")),
            Paragraph(Text("Sharpness for every real parameter. On b = a and c = (a−1)(2a−1), already shown ordered and on h_C(1) = 0 for every a ≥ 2, the same evaluation specializes to h_C(a) = a⁴(a−1)²(2a−1)²(a²−4a+1). At a = κ the final factor is zero, while a differs from zero and one. Therefore a survives both exact polynomial divisions as an actual residual root. The global gap is strict for this family, with λ₄ > s > a; the distinct roots 0,1,a must fill the three earlier positions. Hence λ₂ = 1 and λ₃ = a, each simple, and the smallest residual root equals a.")),
            Paragraph(Text("For every real 2 ≤ a < κ, the displayed prefactor is positive and a²−4a+1 = (a−2)²−3 < 0. Thus χ_C(a) < 0 and no root equals a. The same weak-sign pair subspace still gives 2 ≤ N(a) ≤ 3, because zero and one are below a. Negative determinant forces odd N(a), so N(a) = 3 with multiplicity. Removing the unique zero and just one occurrence of one leaves at least one residual root below a. This establishes the universal sharpness claim without invoking the strict-cutoff isolation outside its hypotheses.")),
            Paragraph(Text("Supplier correspondence and limits. The actual geometry and balanced specialization come from SixSupportLaplacianLowRoot; the real positive-subspace and compression bounds from RHLinalg in Sylvester and Inertia, with the existing invertible-congruence inertia supplier for the spectral count transport. They are cited at repository revision 6b24b302e37ea2ead041655259d42ef4866d3249. The characteristic-root multiset, sorting, polynomial division and finite-dimensional disjointness suppliers are from Mathlib 56a005855ea17e0b0958f73ec801ae140b0a1679; the source note gives direct locators. No complex-only Courant–Fischer specialization or extra third-party import is needed. Existing positive_real_low_eigenvalue supplies an actual low eigenpair but does not certify this sorted-spectrum application. The exact determinant at one is shared with the fixed-gap application below; that application's eventual fixed-gap analytic argument does not replace these all-real counts, equalities or the gap-zero sharpness family. Divisor windows, off-surface generic residual positivity, and equality-curve/genus remain outside this application. The separate equality-spectrum locus c = b(b+2)−a is supplied by the exact matrix-polynomial correspondence below; it does not add ordered-root, simplicity or positivity conclusions. Ideal-graph realization and full three-prime classification retain their separate obligations.")),
            Paragraph(Text("Fixed real gaps at endpoint one. The public proposition prop:fixed-gap-expansion in paper/sections/proof-structure.tex, with the coefficients in lem:endpoint-one-small-gaps in paper/sections/three-prime-classification.tex, concerns this same quotient. Both locators are at the public revision cited above. For every fixed real d ≥ 1, there exist real A_d ≥ 2 and K_d ≥ 0 such that, for every real a ≥ A_d and b = a+d, exactly one real c > b satisfies h_C(1) = 0, where h_C(x) = det(xI−C)/x. Write this root as c*. Its full expansion, with one bound valid for all these a, is")),
            Paragraph(Text("|c* − (2a² + (2d−3)a − (d+2)(2d−1)/2 + d²/(2a) + d²(d+1)(2d−3)/(4a²))| ≤ K_d/a³.")),
            Paragraph(Text("Here C is SixSupportLaplacianLowRoot.quotient a b c, with support order 1,2,3,12,13,23 and weights a,b,c,ab,ac,bc, exactly as displayed above. Disjoint supports interact with entry minus the target weight: the singleton triangle and the three complementary singleton/pair edges are all the off-diagonal interactions. The existing permutation [0,1,2,5,4,3] only reverses the pair coordinates. No symmetric surrogate replaces C in the endpoint calculation. This application is a readable consequence of existing results; it is not an additional Lean theorem certified by the Describe statements above.")),
            Paragraph(Text("The actual determinant. At x = 1 the defining division gives h_C(1) = det(I−C). The following identity holds for all real a,b,c. Set r = 1−a, s = 1−b, u = 1−c, k = 1−a−b−c, N_a = k+ab+ac−bc, N_b = k+ab+bc−ac, and N_c = k+ac+bc−ab. Expanding the determinant gives")),
            Paragraph(Text("det(I−C) = N_a N_b N_c − abrs N_c − acru N_b − bcsu N_a + 2abcrsu.")),
            Paragraph(Text("Indeed each pair vertex in a nonzero determinant permutation is either fixed or transposed with its sole singleton neighbor. Summing these alternatives when a singleton is otherwise fixed yields (1−a)(1−b−c−bc)−abc = N_a and its two cyclic versions. The three singleton transpositions contribute −abrs N_c, −acru N_b and −bcsu N_a. The two oriented singleton 3-cycles together contribute 2abcrsu. These exhaust the nonzero permutation terms. This is a division-free use of Matrix.det_apply (equivalently det_apply') over the commutative ring of real numbers, so it includes parameters equal to one.")),
            Paragraph(Text("For explicit coefficient extraction, put σ = a+b, p = ab, v = 1−σ, w = v+p = rs, z = v−p, m = 1−(a−b)², and L = σ³−4pσ+2p−σ. Then N_a = w+(a−b−1)c, N_b = w+(b−a−1)c, N_c = z−vc. The determinant becomes (z−vc)(wv−2wc+mc²) − c(1−c)(wσv+Lc). Consequently h_C(1) = Q(c) = Ac³+Bc²+Dc+E, where")),
            Paragraph(Text("A = L−vm = a²+b²−1.")),
            Paragraph(Text("B = zm+(σ+2)vw−L = a³−4a²b²+2a²b−a²+2ab²+ab−3a+b³−b²−3b+3.")),
            Paragraph(Text("D = w(2p−3v) = (a−1)(b−1)(2ab+3a+3b−3).")),
            Paragraph(Text("E = wvz = (a−1)(b−1)(a+b−1)(ab+a+b−1).")),
            Paragraph(Text("These are precisely the four public cubic coefficients. Their algebraic identity holds at arbitrary real b = a+d; it does not inherit the restriction d ∈ {1,2} of the separate small-gap bracket lemma. From now on fix an arbitrary real d ≥ 1 and write Q_{a,d} for this cubic at b = a+d.")),
            Paragraph(Text("Polynomial regularization and a real local branch. Define the following real polynomials, with d held fixed:")),
            Paragraph(Text("α(t) = 2+2dt+(d²−1)t².")),
            Paragraph(Text("β(t) = −4+(6−8d)t+(−4d²+9d−1)t²+(5d²−d−6)t³+(d³−d²−3d+3)t⁴.")),
            Paragraph(Text("γ(t) = 2+(4d+2)t+(2d²+3d−13)t²+(d²−13d+12)t³−3(d−1)²t⁴.")),
            Paragraph(Text("δ(t) = 2+(5d−1)t+(4d²−2d−8)t²+(d³−d²−12d+12)t³−6(d−1)²t⁴−(d−1)³t⁵.")),
            Paragraph(Text("Set F(t,y) = α(t)y³+β(t)y²+t²γ(t)y+t³δ(t). At a = 1/t and b = 1/t+d, the coefficient formulas give t²A = α(t), t⁴B = β(t), t⁴D = γ(t) and t⁵E = δ(t) whenever t ≠ 0. Hence F(t,y) = t⁸ Q_{1/t,d}(y/t²) for every real t ≠ 0 and every real y. The displayed polynomial defines F at zero without using an inverse there. It gives F(0,y) = 2y²(y−2), F(0,2) = 0 and F_y(0,2) = 8.")),
            Paragraph(Text("Use the pinned real implicit-function theorem for f : ℝ × ℝ → ℝ, f(t,y) = F(t,y), at (0,2). The polynomial is real analytic, hence C^ω, and the three spaces are complete normed real spaces. The dependent derivative is z ↦ 8z, an invertible continuous linear map with inverse z ↦ z/8. In Mathlib.Analysis.Calculus.ImplicitContDiff the statements ContDiffAt.implicitFunction, implicitFunction_apply_self, eventually_apply_implicitFunction and contDiffAt_implicitFunction apply with n = ω ≠ 0. They provide Y : ℝ → ℝ with Y(0) = 2, F(t,Y(t)) = 0 on a neighborhood of zero, and C^ω regularity at zero. ContDiffAt.analyticAt identifies that regularity with analyticity here; continuity already gives Y(t) → 2. This local supplier is used for existence and continuity, while uniqueness on all c > b is established below.")),
            Paragraph(Text("Coefficients and a common error constant. Use fresh local symbols u = 2d−3, v = −(d+2)(2d−1)/2, w = d²/2 and z = d²(d+1)(2d−3)/4, and let P(t) = 2+ut+vt²+wt³+zt⁴. The coefficients of F(t,P(t)) from degree zero through four vanish. More explicitly, with each successive coefficient using the previous choices, the degree-zero coefficient is 0 and the degree-one through degree-four coefficients are respectively 8u+24−16d, 8v+4(d+2)(2d−1), 8w−4d² and 8z−2d²(d+1)(2d−3). These triangular equations give every coefficient displayed in P.")),
            Paragraph(Text("One can verify these equations directly by writing F(t,2+s) = H(t)+J(t)s+M(t)s²+α(t)s³, where H = 8α+4β+2t²γ+t³δ, J = 12α+4β+t²γ and M = 6α+β. In increasing powers of t, the coefficients needed are H: (0, 24−16d, −8d²+36d−8, 20d²+4d−18, 4d³−d−15), J: (8, 24−8d, −4d²+36d−14, 20d²−22), and M: (8, 4d+6, 2d²+9d−7). Substitution of s = ut+vt²+wt³+zt⁴ yields the preceding triangular equations. Thus Polynomial.X_pow_dvd_iff supplies a real polynomial R_d, of degree at most nine, with the identity F(t,P(t)) = t⁵R_d(t) for every real t. This residual calculation does not assume any derivatives or Taylor coefficients of Y.")),
            Paragraph(Text("Define M_d = 1+|R_d(0)| = 1+|[t⁵]F(t,P(t))| > 0. By Polynomial.continuousAt and Metric.continuousAt_iff, with output tolerance one at zero, there is a positive radius on which |R_d(t)−R_d(0)| < 1. The triangle inequality gives the same bound |R_d(t)| ≤ M_d throughout that neighborhood, hence |F(t,P(t))| ≤ M_d|t|⁵. The constant depends only on the fixed d.")),
            Paragraph(Text("The polynomial F_y is jointly continuous and F_y(0,2) = 8. Continuity with tolerance four, followed by restriction to a smaller product rectangle, gives η > 0 such that |F_y(t,s)−8| ≤ 4 whenever |t| < η and s ∈ B = [2−η,2+η]. Choose η strictly smaller than the original continuity radius so that the closed endpoints are included. Continuity of Y and P, both equal to two at zero, then puts both Y(t) and P(t) in this same convex interval B on a sufficiently small common t-neighborhood.")),
            Paragraph(Text("Now apply D5.S3.Quantum.Tomography.CayleyCoverAnalysis.preconditioned_residual_controls_displacement with E = F = ℝ, the one-variable function f(s) = F(t,s), derivative J(s)(r) = F_y(t,s)r, preconditioner C(r) = r/8, q = 1/2, x = P(t) and y = Y(t). The letters C, J and F in this supplier instance are local to that instance; its preconditioner is not the six-support matrix. The derivative exists everywhere because f is a polynomial. The operator C.comp(J(s))−id is multiplication by (F_y(t,s)−8)/8, whose norm is at most 1/2 throughout B. Convexity and both membership hypotheses hold on the same neighborhood. The supplied inequality therefore gives")),
            Paragraph(Text("(1/2)|Y(t)−P(t)| ≤ (1/8)|F(t,Y(t))−F(t,P(t))| = (1/8)|F(t,P(t))|, hence |Y(t)−P(t)| ≤ (M_d/4)|t|⁵.")),
            Paragraph(Text("This verifies both uniform premises of the quantitative inference: one residual bound and one derivative margin hold for every t in a common neighborhood. No pointwise error, unspecified coefficient match, or unverified remainder assumption is needed.")),
            Paragraph(Text("Eventual signs and placement. Let U(t) = 1+dt and S_d(t) = tα(t)U(t)³+β(t)U(t)²+tγ(t)U(t)+tδ(t). The polynomial identities give F(t,t+dt²) = t²S_d(t) and S_d(0) = −4. Continuity with tolerance two makes S_d(t) < 0 on a neighborhood of zero. At t = 1/a > 0 the scaling identity therefore gives Q_{a,d}(a+d) = a⁶S_d(1/a) < 0 for all sufficiently large real a. In addition S_d(t) = −4+tT_d(t) for a polynomial T_d; its continuity yields the source estimate Q_{a,d}(a+d) = −4a⁶+O_d(a⁵). The sign used here follows directly from S_d(0), without assuming that estimate.")),
            Paragraph(Text("Choose one ε_d > 0, at most one, small enough for the branch equation, residual bound, derivative margin, both interval memberships, the sign of S_d and Y(t) > 1 whenever |t| < ε_d. Each holds on a neighborhood already obtained, so a finite intersection provides this one radius. Define A_d = max{2,d+2,2/ε_d} and K_d = M_d/4. For every real a ≥ A_d, t = 1/a satisfies 0 < t < ε_d. Set c* = a²Y(1/a). The scaling identity makes it a root of the actual endpoint equation. Also c* > a², and a ≥ d+2 gives b = a+d < 2a ≤ a². Thus c* > b.")),
            Paragraph(Text("Global uniqueness above b. At these same parameters a ≥ 2 and b ≥ 3, the coefficients A = a²+b²−1 and E = (a−1)(b−1)(a+b−1)(ab+a+b−1) are positive. Hence Q(0) > 0 > Q(b). The polynomial x ↦ Q(−x) has degree three and leading coefficient −A < 0; Polynomial.tendsto_atBot_of_leadingCoeff_nonpos makes it tend to minus infinity as x tends to plus infinity. Choose l < 0 with Q(l) < 0. The intermediate-value theorem on [l,0] and [0,b] supplies roots in the open intervals (l,0) and (0,b), since their endpoint signs are strict. Along with c* > b these are three distinct real roots. A nonzero polynomial of degree three has at most three distinct roots, by Polynomial.mem_roots and Polynomial.card_le_degree_of_subset_roots. Any other root anywhere in (b,∞) would yield a four-element set of roots, a contradiction. Thus the uniqueness conclusion is global on the required half-line.")),
            Paragraph(Text("Finally divide |Y(t)−P(t)| ≤ (M_d/4)|t|⁵ by t² > 0. Since a²P(1/a) is exactly 2a²+(2d−3)a−(d+2)(2d−1)/2+d²/(2a)+d²(d+1)(2d−3)/(4a²), this gives the stated bound K_d/a³ for every real a ≥ A_d. Equivalently Asymptotics.isBigO_iff expresses the remainder as O_d(a^(−3)) at plus infinity. The construction has the quantifier order: for every fixed real d ≥ 1, choose A_d and K_d once, then the existence, global uniqueness and bound hold for every real a above that threshold.")),
            Paragraph(Text("Supplier correspondence and scope. The quotient, weights and permutation are reused from the owning D5 module, and the quantitative inequality from CayleyCoverAnalysis, at repository revision 6b24b302e37ea2ead041655259d42ef4866d3249. The analytic, polynomial, continuity, intermediate-value and root-count statements used here are from Mathlib revision 56a005855ea17e0b0958f73ec801ae140b0a1679; the source note gives their direct locators. The proof uses only real parameters and establishes no uniformity for growing d. At d = 1 the full expansion is 2a²−a−3/2+1/(2a)−1/(2a²)+O(a^(−3)); the valid small-gap bracket anchor 2a²−a−2 is a different expression. At d = 2 it is 2a²+a−6+2/a+3/a²+O(a^(−3)). The application concerns the existing weighted quotient. Realization by an ideal graph and the whole graph classification require their separate hypotheses and arguments; this supplementary consequence supplies neither a classification nor a literature novelty claim.")),
            EndpointCoefficientWindow(),
            ClosedResidualPositivity(),
            EqualityLocusSpectrum(),
            ResidualApplicationEvidenceScope(),
            ExactMatrixPolynomialCorrespondence(),
            ExactQuarticAlgebra(),
            IntegerFiniteness())));

    private static DocumentBlock EndpointCoefficientWindow()
    {
        return new DocumentBlock.Section(H("The actual residual quartic and its strict coefficient window"),Blocks(
            Paragraph(Text("Keep the literal C = SixSupportLaplacianLowRoot.quotient a b c in support order 1,2,3,12,13,23. Write χ_C for its characteristic polynomial and h_C = χ_C.divX, so χ_C(X) = X h_C(X) by exact monic division. For positive parameters, the positive diagonal similarity and support permutation above identify its complete characteristic-root multiset with that of the existing real symmetric S. In this section and the next two, the symbols A,B,D,N and F refer to the residual quartic coefficients and polynomial; they are distinct from the coefficients, discriminant, norm numerator and field F in the equality-curve tower.")),
            Paragraph(Text("For arbitrary real a,b,c, put s = a+b+c, p = ab+ac+bc and r = abc. Define A = p+3s−1, B = sr+2sp+3s²−3s+1, D = r²+(s²−s+1)r+s²p+p²+(s−1)³, and N = rs(p+s). The explicit monic quartic is F(X) = X⁴−AX³+BX²−DX+N. These coefficient definitions carry no endpoint or ordering assumption.")),
            Paragraph(Text("The division-free leaf/triangle determinant identity for the literal quotient gives h_C(X) = X h_C(1)+(X−1)F(X), for every real parameter triple. Evaluation gives h_C(x) = x h_C(1)+(x−1)F(x) for every real x, including x = 1. Differentiating the polynomial identity and evaluating at one gives F(1) = h_C′(1)−h_C(1). These are polynomial equalities, with no division by x−1. On h_C(1) = 0, exact monic division identifies F with h_C/(X−1). Outside that surface F need not be this monic-division quotient and its roots are not identified with quotient roots.")),
            Paragraph(Text("Now consider any ordered real triple 4 ≤ a ≤ b ≤ c with actual h_C(1) = 0. Since 4 > 2+sqrt(3), the full endpoint-isolation application supplies the four actual residual roots μ₁,…,μ₄ with algebraic multiplicity. With U = min{c,a+b}, they satisfy a < μ₁ < U and s < μ₂ ≤ μ₃ ≤ μ₄. Thus F(X) = ∏ᵢ₌₁⁴(X−μᵢ), its root multiset is {μ₁,μ₂,μ₃,μ₄}, and χ_C(X) = X(X−1)F(X). In particular det(xI−C) = x(x−1)F(x) for every real x, including zero and one. The complete quotient-root multiset is {0,1,μ₁,μ₂,μ₃,μ₄}; zero, one and μ₁ each have algebraic multiplicity one, since μ₁ < a+b < s < μ₂; repeated high residual roots are permitted.")),
            Paragraph(Text("Comparing coefficients of this actual split product gives every Vieta identity: Σᵢ μᵢ = A, Σᵢ<ⱼ μᵢμⱼ = B, Σᵢ<ⱼ<ₖ μᵢμⱼμₖ = D and μ₁μ₂μ₃μ₄ = N. All four roots are positive. Dividing the third identity by the nonzero product gives D/N = 1/μ₁+1/μ₂+1/μ₃+1/μ₄. This argument retains multiplicities throughout.")),
            Paragraph(Text("Set R = 2/s+1/(A−U−2s). Before taking reciprocals, s,p,r,N are positive, and p > U+1: indeed ac ≥ 4c and ab,bc ≥ 16 imply p > c+1 ≥ U+1. Therefore A−U−2s = p+s−1−U > s > 0, and 0 < R < 3/s. Also s/r = 1/(ab)+1/(ac)+1/(bc) ≤ 3/16, so 3r ≥ 16s and r > 4s. Finally 2(s²−3p) = (a−b)²+(a−c)²+(b−c)² ≥ 0, and s−1 > 0.")),
            Paragraph(Text("Expansion of the displayed coefficients gives D−3N/s = r(r−4s)+r(s²−3p+1)+s²p+p²+(s−1)³ > 0. Every term is nonnegative and the first term is strictly positive. Since N > 0 and R < 3/s, it follows that D−NR > D−3N/s > 0 and D > 0. Thus s, all μᵢ, A−U−2s, N, D and D−NR are positive; every reciprocal and quotient used in the window has a justified positive denominator.")),
            Paragraph(Text("For x,y > s > 0, the exact scalar identity 1/s+1/(x+y−s)−1/x−1/y = (x−s)(y−s)(x+y)/(sxy(x+y−s)) has a strictly positive right side. Apply it to μ₂,μ₃, and then to μ₂+μ₃−s,μ₄. It gives 0 < H = 1/μ₂+1/μ₃+1/μ₄ < 2/s+1/(μ₂+μ₃+μ₄−2s). The Vieta sum and μ₁ < U give μ₂+μ₃+μ₄−2s = A−μ₁−2s > A−U−2s > 0, so H < R. Strictness comes from μ₂,μ₃,μ₄ > s and permits equality between high roots.")),
            Paragraph(Text("Now D/N = 1/μ₁+H and 0 < H < R imply (D−NR)/N < 1/μ₁ < D/N. Inverting positive quantities and combining with a < μ₁ < U yields the exact strict window max{a,N/D} < μ₁ < min{U,N/(D−NR)}. Both bounds are strict on the entire stated real domain; neither the endpoints nor the ordering hypotheses have been dropped.")),
            Paragraph(Text("For the arithmetic specialization assume a,b,c are integers with 4 ≤ a ≤ b ≤ c and actual h_C(1) = 0 after injection into the reals. Form the same literal six-by-six matrix C_ℤ over ℤ, and F_ℤ = (χ_Cℤ /ₘ X) /ₘ (X−1). Entrywise integer-to-real injection sends C_ℤ to C. Characteristic polynomials commute with this map, as do both divisions by the monic X and X−1. Hence F_ℤ maps to the actual F. Injectivity transfers monicity, degree four and the exact factorization χ_Cℤ = X(X−1)F_ℤ, and its constant coefficient is N_ℤ = abc(a+b+c)(ab+ac+bc+a+b+c). The first division is exact from the kernel; the endpoint hypothesis makes the second exact.")),
            Paragraph(Text("If d is an integer whose real image is the smallest actual residual root μ₁, then F_ℤ(d) = 0 by the injective coefficient map. Polynomial.IsRoot.dvd_coeff_zero gives d dividing N_ℤ, and μ₁ > a ≥ 4 gives d > 0. That d obeys max{a,N/D} < d < min{U,N/(D−NR)}, with the coefficients and fractions evaluated in the reals. Separately, each of the other three residual roots that is an integer is at least a+b+c+1, since it is strictly greater than the integer s. No assumption that all four roots are integers is needed. Divisibility and these windows are necessary conditions only: they assert no converse, sufficiency, splitting criterion, finite enumeration or unbounded exclusion.")),
            Paragraph(Text("The coefficient-window mathematics is attributed to the endpoint-one corollary in paper/sections/endpoint-one-spectrum.tex at b93becea662a746badeadba42fdc3d3eb3db9382 and the total-sum note at 4a451ac51055c6d04926967749196f12ac8e49c8. The written argument follows the actual endpoint quartic, full G isolation, coefficient comparison and two strict reciprocal merges supplied by the completed transient applications. Their evidence scope is stated after these three sections; the existing Describe bindings retain their original statements."))));
    }

    private static DocumentBlock ClosedResidualPositivity()
    {
        return new DocumentBlock.Section(H("Closed residual positivity for arbitrary unsorted parameters"),Blocks(
            Paragraph(Text("For every unsorted real triple a,b,c ≥ 8 and every x in the closed interval 0 ≤ x ≤ 4, the explicit generic quartic F above satisfies F(x) > 0. No endpoint, parity, upper-size or parameter-ordering hypothesis enters this positivity statement. Its off-surface polynomial identity and continuation at x = 1 are the actual determinant identities established in the preceding section.")),
            Paragraph(Text("Define the homogeneous expression J(a,b,c;v,w) = 256v⁴−64Av³(v+w)+16Bv²(v+w)²−4Dv(v+w)³+N(v+w)⁴, using the same A,B,D,N at a,b,c. For each row (i,j,k) in the complete table below, let (g₀,g₁,g₂,g₃,g₄) be its five entries and put P(m,t,u;v,w) = Σ_rows mⁱtʲuᵏ Σ_ell=0⁴ g_ell v^ell w^(4−ell). The full coefficient identity is J(8+m,8+m+t,8+m+t+u;v,w) = P(m,t,u;v,w) for every real m,t,u,v,w. It includes equality of coefficients outside the displayed support, where the coefficients are zero.")),
            Paragraph(Text("The 70 rows and all 350 coefficient strings are those of notes/endpoint-one-spectral-gap.md at public revision 95d8d9a90d4ef0aa06be8ba5ce70d3355838385c. Their orientation is ascending powers of v, homogenized as v^ell w^(4−ell). The actual native identity expands the explicit determinant-bound A,B,D,N and the whole displayed sum. Textual row correspondence identifies the public data; the full polynomial identity supplies its algebraic connection to F. Neither a selected row nor a numerical anchor supplies that connection.")),
            Paragraph(Text("All displayed coefficients are positive. If m,t,u,v,w are nonnegative and v+w > 0, every term of P is nonnegative. Its (0,0,0) row is already strictly positive: if w > 0 its 2654208w⁴ term is positive, and if w = 0 then v > 0 and its 188596v⁴ term is positive. Thus P > 0 without requiring positive parameter increments.")),
            Paragraph(Text("For sorted 8 ≤ a ≤ b ≤ c, set m = a−8, t = b−a, u = c−b, v = x and w = 4−x. All five variables are nonnegative on the entire closed interval and v+w = 4 > 0. Direct homogeneous substitution gives J(a,b,c;x,4−x) = 256F(x), so the table proves F(x) > 0 there. At x = 0 it uses the w⁴ coefficients; at x = 4 it uses the v⁴ coefficients. The strict values at both endpoints follow directly, and x = 1 is covered by v = 1,w = 3. No limiting argument or division by 4−x is used for this closed-interval proof.")),
            Paragraph(Text("The original rational form of the same complete identity is also retained: for every real m,t,u and every z ≥ 0, (1+z)⁴F(8+m,8+m+t,8+m+t+u;4z/(1+z)) = P(m,t,u;z,1). Here F(a,b,c;x) means evaluation of the explicit quartic at those parameters, and 1+z > 0. On 0 ≤ x < 4 the inverse z = x/(4−x) recovers this form, with positive denominator. The homogeneous argument above supplies x = 4 directly as well.")),
            Paragraph(Text("The scalar formula in s,p,r gives the exact symmetries F(a,b,c;x) = F(b,a,c;x) and F(a,b,c;x) = F(a,c,b;x) for every real a,b,c,x. These two adjacent swaps cover all six weak ordering cases, including ties. Sorting any original unsorted triple with each entry at least eight and transporting the scalar value proves the same closed positivity for that original triple. This uses scalar polynomial symmetry and makes no unproved matrix-permutation assertion.")),
            Paragraph(Text("Now add actual h_C(1) = 0 for that unsorted triple. Exact division gives χ_C(X) = X(X−1)F(X), with F monic of degree four. Positive weights and the established similarity supply a split real characteristic polynomial with one simple zero and five positive roots. Thus F also splits over the reals and its root multiset has four entries, all positive. The complete quotient-root multiset is {0,1}+F.roots. Strict F(x) > 0 on the closed interval excludes every residual root there, so all four residual roots are strictly greater than four. In particular F(1) > 0 and h_C′(1) = F(1) > 0; the quotient root one has algebraic multiplicity exactly one and is the smallest positive root. High-root repetitions remain allowed. If those four roots happen to be integers, each is at least five; this is a location restriction, not an obstruction to integral splitting or a classification.")),
            Paragraph(Text("The following is the complete table used in the identity. Each row lists (i,j,k) followed by (g₀,g₁,g₂,g₃,g₄); all other (i,j,k) coefficients are zero. This finite polynomial identity proves a theorem on the entire unbounded real orthant. Off h_C(1) = 0, positivity still holds but F.roots are not asserted to be quotient roots.")),
            Paragraph(Text("(0,0,0): (2654208,7797220,7836988,2882316,188596).")),
            Paragraph(Text("(0,0,1): (651264,2000436,2147180,896892,98884).")),
