    private static DocumentBlock ExactMatrixPolynomialCorrespondence()
    {
        return new DocumentBlock.Section(H("Exact actual matrix and characteristic-polynomial correspondence"),Blocks(
            Paragraph(Text("The complete matrix correspondence is for the existing LowRoot carrier itself. In support order 1,2,3,12,13,23, C = SixSupportLaplacianLowRoot.quotient a b c is the literal six-by-six matrix with diagonal entries b+c+bc, a+c+ac, a+b+ab, c, b, a and off-diagonal entries −b, −c, −bc, −a, −ac, −ab in the displayed support positions. This is the D−A sign convention: each edge interaction is the negative of its target weight. Its support weights are a,b,c,ab,ac,bc. No symmetric surrogate is substituted for this carrier.")),
            Paragraph(Text("The same literal matrix is defined over every commutative ring R. The universal integer model uses Z[x₀,x₁,x₂] and the rational model uses Q[x₀,x₁,x₂]; coefficientwise specialization to any commutative ring, and to every Q-algebra for the rational model, returns the actual matrix. The maps commute with the matrix, its characteristic polynomial and exact divX operation. Thus the integer, rational and arbitrary-parameter readings are coefficient extensions of one matrix definition, not separate named matrices.")),
            Paragraph(Text("Write χ_C(X) for the characteristic polynomial and h_C(X) for χ_C.divX. The constant coefficient of χ_C is zero because the all-one vector is an exact kernel vector over every commutative ring. Polynomial X_mul_divX_add therefore gives the literal identity χ_C(X) = X h_C(X), with zero remainder; divX is exact polynomial division and does not mean pointwise division at X=0. Over a nontrivial coefficient ring the six-by-six characteristic polynomial has degree six and h_C has degree five. These degree statements are ring-theoretic and make no positivity, ordering or root-simplicity assumption.")),
            Paragraph(Text("For every parameter triple, evaluation at one is tied to the same carrier by h_C(1) = det(I−C). On the endpoint substitution c = t−a with t = b(b+2), put q = a(t−a), A = 3b−1, B = b(b²+4b−1), and C₀ = −(b²+2b−1)(b²+3b−1)(b³+3b²+3b−1). Define G(a,b) = A q² + B q + C₀. The literal determinant calculation over the universal ring, followed by coefficient extension, gives for all commutative-ring parameters h_C(a,b,t−a)(1) = −(b−1)G(a,b). The factor b−1 is retained; it is not canceled.")),
            Paragraph(Text("Regard G as a polynomial in a over Q[b]. Its a-degree is exactly four. Regard the same expression as a polynomial in independent a,b; its total degree is exactly seven and the coefficient of a⁰b⁷ is −1. These are coefficient identities for the actual endpoint polynomial, not degree estimates for a reduced or canceled expression.")),
            Paragraph(Text("For real a,b, the actual matrix spectrum has value one exactly when b = 1 or G(a,b) = 0: (1 ∈ spectrum ℝ (SixSupportLaplacianLowRoot.quotient a b (t−a))) ↔ (b = 1 ∨ G(a,b) = 0). The b = 1 component is a genuine component of the actual spectrum locus and remains present for every real a. This equivalence is algebraic and carries no ordered-root, simplicity, positivity, or endpoint-domain hypothesis.")),
            Paragraph(Text("Literal bridge to the quartic tower. The endpoint polynomial just defined is coefficientwise the actualQuartic used in the characteristic-zero tower. After mapping Q[b] into k[b] and then K = RatFunc k, the resulting polynomial in the fresh quartic parameter variable X, representing a, is the literal g(X) = A X⁴ − 2At X³ + (At²−B)X² + BtX + C₀. In the actual fields H = K(y) with y² = D and F = H(z) with z² = f, the chosen a = (t+z)/2 satisfies q = a(t−a), y = 2Aq+B and z = 2a−t. Those recovery identities prove that the endpoint polynomial evaluated at the tower generator is zero and that the tower generator is the same root of the literal g. The quartic quotient K[X]/(g) ≃ F and the coefficient extension are therefore bridges between the actual matrix endpoint expression and the actual field tower, rather than identifications made from declaration names.")),
            Paragraph(Text("Authority and limits. The matrix identities, universal/rational specializations, degree facts, endpoint factor, coefficient and spectrum assertions are supplied by the complete matrix proof source and its source-bound actual result. This section is readable application exposition; it adds no retained Lean, Reg, Describe, freeze or positive-certificate declaration. The existing real global spectral theorem and fixed-gap argument remain in force, while the separately owed smooth models, local branches, genus, Riemann–Hurwitz, geometric finiteness interfaces, graph realization and full classification remain outside this source preparation."))));
    }

    private static DocumentBlock ExactQuarticAlgebra()
    {
        Formula b=V("b"),t=V("t"),aa=V("A"),bb=V("B"),dd=V("D"),nn=V("N");
        Formula c0=new Formula.Subscript(V("C"),Num(0));
        Formula q=V("q"),f=V("f"),y=V("y"),z=V("z"),av=V("a"),xx=V("X");
        return new DocumentBlock.Section(H("The exact quartic algebra over characteristic-zero fields"),Blocks(
            Paragraph(Text("The equality-curve remark rem:endpoint-one-equality-curve in paper/sections/endpoint-one-spectrum.tex at public revision b93becea662a746badeadba42fdc3d3eb3db9382 supplies the polynomial used here. Its linked curve note at revision 8ed4f9014f6142949e6af40fd16e18ca304f629a supplies the displayed discriminant and norm numerator. The polynomial and those parameters are attributed to that source. The following derivation is an application of existing integral-closure, quadratic-algebra, Kummer, minimal-polynomial and Gauss results, not a novelty claim. The existing Describe statements retain their stated quotient geometry, low-root and balanced scope; this application adds no Lean declaration or Describe theorem.")),
            Paragraph(Text("Let k be any field of characteristic zero, let b be an indeterminate, and put K = k(b), represented by RatFunc k. Map rational coefficients into k[b] and then into K; these maps are injective. We keep the same letters for the images. No algebraic-closedness assumption on k is needed for the field-tower argument. In this section C₀ is the scalar constant coefficient, distinct from the six-support matrix C; the next integer-finiteness section denotes this same scalar by C. Define the literal polynomials")),
            Equation(t,Mul(b,Add(b,Num(2)))),
            Equation(aa,Sub(Mul(Num(3),b),Num(1))),
            Equation(bb,Mul(b,Sub(Add(Pow(b,2),Mul(Num(4),b)),Num(1)))),
            Equation(c0,Negate(Mul(Mul(Sub(Add(Pow(b,2),Mul(Num(2),b)),Num(1)),Sub(Add(Pow(b,2),Mul(Num(3),b)),Num(1))),Sub(Sum(Pow(b,3),Mul(Num(3),Pow(b,2)),Mul(Num(3),b)),Num(1))))),
            Equation(dd,Sum(Mul(Num(12),Pow(b,8)),Mul(Num(92),Pow(b,7)),Mul(Num(233),Pow(b,6)),Mul(Num(172),Pow(b,5)),Mul(Negate(Num(154)),Pow(b,4)),Mul(Negate(Num(172)),Pow(b,3)),Mul(Num(161),Pow(b,2)),Mul(Negate(Num(44)),b),Num(4))),
            Equation(nn,Mul(Sub(Sum(Pow(b,3),Mul(Num(5),Pow(b,2)),Mul(Num(6),b)),Num(2)),Sum(Mul(Num(3),Pow(b,6)),Mul(Num(8),Pow(b,5)),Mul(Negate(Num(6)),Pow(b,4)),Mul(Negate(Num(36)),Pow(b,3)),Mul(Negate(Num(28)),Pow(b,2)),Mul(Num(40),b),Negate(Num(8))))),
            Paragraph(Text("For the plane variable a, write q = a(t−a). The polynomial is quartic in a, with coefficients in k[b]:")),
            Equation(Call("G",av,b),Sum(Mul(aa,Pow(Mul(av,Sub(t,av)),2)),Mul(bb,Mul(av,Sub(t,av))),c0)),
            Paragraph(Text("Exact polynomial identities and branch prerequisites. Polynomial normalization gives both identities below. The degrees of D and N are eight and nine; a prime denotes differentiation in b. Explicit rational Bézout identities for (D,D′), (N,N′) and (N,D) give their normalized gcds equal to one; mapping each Bézout equality into k[b] preserves coprimality. Thus D and N are squarefree, and their root sets are disjoint in an algebraic closure. These are exact identities for these polynomials, rather than assumed squarefreeness or norm certificates.")),
            Equation(Sub(Pow(bb,2),Mul(Num(4),Mul(aa,c0))),dd),
            Equation(Sum(Mul(aa,Pow(t,4)),Mul(Num(4),Mul(bb,Pow(t,2))),Mul(Num(16),c0)),nn),
            Equation(Call("gcd",dd,Call("derivative",dd)),Num(1)),
            Equation(Call("gcd",nn,Call("derivative",nn)),Num(1)),
            Equation(Call("gcd",nn,dd),Num(1)),
            Paragraph(Text("For explicit Bézout witnesses, a coefficient list (c₀,…,cₘ) denotes the polynomial Σᵢ cᵢbⁱ, in ascending powers of b. The following rational coefficient lists satisfy U_D D+V_D D′ = 1, U_N N+V_N N′ = 1 and U_ND N+V_ND D = 1, respectively. These identities can be read as polynomial equalities before mapping to k[b].")),
            Paragraph(Text("U_D = (15077458503622003/12603918688, -54128905348874963/12603918688, -6246087705771407/3150979672, 117940112961877943/12603918688, 145006858328612117/12603918688, 30779539539563445/6301959344, 551481433980327/787744918).")),
            Paragraph(Text("V_D = (1370677759331121/12603918688, -19934798047738501/25207837376, 36019683710933693/25207837376, 8204653143188935/12603918688, -44366105575549787/25207837376, -47526676857220537/25207837376, -1093986370835811/1575489836, -551481433980327/6301959344).")),
            Paragraph(Text("U_N = (-1551720656793517/69254786592, 290115890479151/46169857728, 6813283610138383/92339715456, 34122483667637429/554038292736, 3370077294694969/2216153170944, -86652849207243331/4432306341888, -39894848329397747/4432306341888, -417181352926057/328318988288).")),
            Paragraph(Text("V_N = (-1551724985217679/554038292736, 13284078298392293/1108076585472, -27151801510553/123119620608, -13019587671423695/738717723648, -1608792935985931/130361951232, -192340276236565/492478482432, 2030298571254023/738717723648, 9931651975121645/8864612683776, 417181352926057/2954870894592).")),
            Paragraph(Text("U_ND = (-3559310030328403/471932176, 6462996085656055/117983044, -46657822536661549/471932176, -21303192533434097/471932176, 14356909865819141/117983044, 61549445215520121/471932176, 5667971824526075/117983044, 714366125043951/117983044).")),
            Paragraph(Text("V_ND = (889827514956041/29495761, -3793513481796410/29495761, 61458663986279/29495761, 22274907297181941/117983044, 15611438025308693/117983044, 249440883003581/58991522, -13899098543371799/471932176, -5667971824526075/471932176, -714366125043951/471932176).")),
            Paragraph(Text("At r = 1/3 the exact values are A(r) = 0, A′(r) = 3, B(r) = 4/27, D(r) = 16/729 and N(r) = 368/729. The nonzero rational values remain nonzero in every characteristic-zero k. The gcds and these values are prerequisites for the later branch analysis; they do not identify any local ring or ramification point on a model.")),
            Paragraph(Text("The first actual quadratic field. Coprimality with D′ makes D separable, hence squarefree, after coefficient extension. If x² = D in K, the integral-closure result IsIntegrallyClosed.exists_algebraMap_eq_of_isIntegral_pow, applied to the polynomial ring k[b] and its fraction field K, supplies a polynomial w whose image is x. Injectivity then gives D = w² in k[b]. Squarefreeness forces w to be a unit, which would make D a unit of degree zero, contrary to degree eight. Thus D is nonsquare in K, with this premise proved for the displayed D.")),
            Paragraph(Text("The existing QuadraticAlgebra field instance therefore constructs the field H = QuadraticAlgebra K D 0, with generator y = omega satisfying y² = D. Its basis 1,y and finrank_eq_two give [H:K] = 2, and adjoin_omega_eq_top gives H = K(y). The prime-two instance of Polynomial.X_pow_sub_C_irreducible_iff_of_prime shows X²−D is irreducible; minpoly.eq_of_irreducible_of_monic identifies it as minpoly_K(y). The polynomial A has leading coefficient 3 ≠ 0, so its image in K and then H is nonzero and invertible. Define")),
            Equation(q,Div(Sub(y,bb),Mul(Num(2),aa))),
            Equation(f,Sub(Pow(t,2),Mul(Num(4),q))),
            Equation(f,Sub(Add(Pow(t,2),Div(Mul(Num(2),bb),aa)),Div(Mul(Num(2),y),aa))),
            Paragraph(Text("Using y² = D and B²−4AC₀ = D gives Aq²+Bq+C₀ = 0 and y = 2Aq+B. Here q is an actual element of H, and y = 2Aq+B puts its generator in K(q), so H = K(q). The first quadratic conjugation fixes K and sends y to −y. Its norm calculation is")),
            Equation(Call("Norm",V("H"),V("K"),f),Sub(Pow(Add(Pow(t,2),Div(Mul(Num(2),bb),aa)),2),Div(Mul(Num(4),dd),Pow(aa,2)))),
            Equation(Call("Norm",V("H"),V("K"),f),Div(Sum(Mul(aa,Pow(t,4)),Mul(Num(4),Mul(bb,Pow(t,2))),Mul(Num(16),c0)),aa)),
            Equation(Call("Norm",V("H"),V("K"),f),Div(nn,aa)),
            Paragraph(Text("QuadraticAlgebra.norm_def supplies the expression u²−Dv² for u+vy. QuadraticAlgebra.det_toLinearMap_eq_norm, together with Algebra.norm_apply, identifies that expression with the actual field norm Algebra.norm K on H. Therefore its multiplicativity is available for the nonsquare inference, rather than being an unproved norm interpretation.")),
            Paragraph(Text("A proved simple rational-field pole. Since A = 3(b−r) and N(r) ≠ 0, the reduced monic RatFunc denominator of N/A is exactly b−r, with root multiplicity one. The denominator-divisibility, cross-multiplication and monicity results for RatFunc give this reduced-denominator statement. N/A is nonsquare by a direct algebraic obstruction: if x² = N/A in K, then (Ax)² = AN. The same integral-closure supplier gives w in k[b] with w² = AN. Evaluation at r forces w(r) = 0. Differentiating the polynomial identity and evaluating at r would force 0 = A′(r)N(r) = 3·368/729, which is nonzero in characteristic zero. This proves the simple-pole nonsquare without assuming a valuation certificate. It concerns the rational base field; it does not yet prove orders at either of the two places of H over r.")),
            Paragraph(Text("The second actual quadratic field. If f were a square in H, multiplicativity of the actual field norm would make N/A a square in K. Thus f is nonsquare. The existing field instance now constructs F = QuadraticAlgebra H f 0 = H(z), with z = omega, z² = f, [F:H] = 2 and minpoly_H(z) = X²−f. The Kummer irreducibility and generation suppliers apply with the proved f-nonsquare premise, just as at the first step. Module.finrank_mul_finrank on the actual scalar tower gives [F:K] = 4. Both quadratic steps and F/K are finite separable extensions: all the fields have characteristic zero, and their finite algebraic extensions are separable. No smooth model or full constant-field assertion is used to obtain these field-level statements.")),
            Paragraph(Text("The actual quartic generator. In F choose a = (t+z)/2, using the embeddings K → H → F consistently. The sign of y is fixed by q = (y−B)/(2A). The equations z² = f and Aq²+Bq+C₀ = 0 give the recovery identities")),
            Equation(q,Mul(av,Sub(t,av))),
            Equation(y,Add(Mul(Num(2),Mul(aa,Mul(av,Sub(t,av)))),bb)),
            Equation(z,Sub(Mul(Num(2),av),t)),
            Paragraph(Text("Every element of H is h₀+h₁y with h₀,h₁ in K, and every element of F is u+vz with u,v in H, by QuadraticAlgebra.re_smul_add_im_smul. The recovery formulas put y and z in K(a); these decompositions then put all of H and F in K(a). Hence F = K(a) = k(b,a), with a genuinely generating the field already constructed. Field.primitive_element_iff_minpoly_natDegree_eq gives degree four for minpoly_K(a).")),
            Paragraph(Text("To bind that generator to the literal polynomial, let X be a fresh polynomial variable and put g(X) = A[X(t−X)]²+B[X(t−X)]+C₀ in K[X]. Its expansion is")),
            Equation(Call("g",xx),Sum(Mul(aa,Pow(xx,4)),Mul(Negate(Num(2)),Mul(aa,Mul(t,Pow(xx,3)))),Mul(Sub(Mul(aa,Pow(t,2)),bb),Pow(xx,2)),Mul(Mul(bb,t),xx),c0)),
            Paragraph(Text("Thus g has degree four and leading coefficient A ≠ 0, and the actual a satisfies g(a) = 0. Its monic normalization A⁻¹g has the same degree and vanishes at a, so minpoly.unique_of_degree_le_degree_minpoly gives A⁻¹g = minpoly_K(a). Irreducibility of the minimal polynomial and multiplication by the nonzero constant A give irreducibility of g in K[X]. The argument uses this original g throughout.")),
            Paragraph(Text("The root-preserving polynomial quotient. Because g and A⁻¹g are associated, AdjoinRoot.algEquivOfAssociated identifies their quotients; AdjoinRoot.algEquivOfEq then uses A⁻¹g = minpoly_K(a). The existing minpoly.equivAdjoin and the proved generation identify the latter quotient with all of F. The composite is a K-algebra equivalence K[X]/(g) = AdjoinRoot(g) ≃ F, sending the residue root to the chosen a. The recovery formulas above identify y and z in its image as well. This supplies the actual quartic-polynomial/field correspondence, separately from the matrix/characteristic-polynomial correspondence.")),
            Paragraph(Text("Primitivity and absolute polynomial irreducibility. Work first in k[b][X], before passing to its fraction field in b. The polynomial A is a nonzero scalar multiple of b−1/3, while B(1/3) = 4/27 ≠ 0, so A and B are coprime in k[b]. A divisor common to all coefficients of G divides the coefficients A of X⁴ and At²−B of X²; it therefore divides B and is a unit. This proves that the literal quartic is primitive. Polynomial.IsPrimitive.irreducible_iff_irreducible_map_fraction_map now transfers the proved irreducibility in K[X] back to k[b][X].")),
            Paragraph(Text("For coefficient extension, let G_ℚ denote precisely A[X(t−X)]²+B[X(t−X)]+C₀ in ℚ[b][X]. The coefficientwise homomorphism pk : ℚ[b] → k[b], induced by ℚ → k, sends G_ℚ to exactly the plane polynomial just used; its further map to K[X] is g. Consequently the original rational polynomial remains irreducible after this coefficient extension for every characteristic-zero k. In particular, taking k = AlgebraicClosure ℚ proves irreducibility of map(pk)(G_ℚ) in (AlgebraicClosure ℚ)[b][X]. This is the actual absolute polynomial irreducibility statement, rather than only irreducibility over ℚ(b). It supplies no smooth projective model or genus computation.")),
            Paragraph(Text("Second conjugation and fixed elements. The involution of the second quadratic algebra fixes H and sends z to −z, so it sends a to t−a and fixes q = a(t−a) and y = 2Aq+B. For u = u₀+u₁z with u₀,u₁ in H, conjugation gives u₀−u₁z. Since 2 ≠ 0 and 1,z are independent, it fixes u exactly when u₁ = 0, exactly when u is in the image of H in F. This identifies the field fixed elements with H. It does not construct a quotient morphism between smooth models.")),
            Paragraph(Text("Supplier correspondence. The applications above use Mathlib revision 56a005855ea17e0b0958f73ec801ae140b0a1679: IsIntegrallyClosed.exists_algebraMap_eq_of_isIntegral_pow for both nonsquare obstructions; QuadraticAlgebra's field instance, finrank_eq_two, omega_mul_omega_eq_algebraMap, re_smul_add_im_smul, adjoin_omega_eq_top, norm_def and det_toLinearMap_eq_norm for the actual fields, generators, degrees, norm and conjugation; Polynomial.X_pow_sub_C_irreducible_iff_of_prime and minpoly.eq_of_irreducible_of_monic for the two quadratic minimal polynomials; Module.finrank_mul_finrank and Field.primitive_element_iff_minpoly_natDegree_eq for the degree-four generator; minpoly.unique_of_degree_le_degree_minpoly, minpoly.equivAdjoin and AdjoinRoot.algEquivOfAssociated/algEquivOfEq for its minimal polynomial and quotient; and Polynomial.IsPrimitive.irreducible_iff_irreducible_map_fraction_map for Gauss transfer. The owning Library note gives direct public source locators. These are existing suppliers applied to the displayed parameters; this exposition retains no named transient checking wrappers or positive-instance declarations.")),
            Paragraph(Text("Remaining E3 boundary. The exact E3.00 universal six-support polynomial/characteristic-polynomial bridge, exact X division, substitution c = b(b+2)−a, identity h_C(1) = −(b−1)G, and faithful matrix correspondence are supplied in the “Exact actual matrix and characteristic-polynomial correspondence” section. The literal quartic quotient equivalence is separately tied to the bridge in that same section. The algebra portions of E3.01–E3.02 and E3.06–E3.08 are the discriminant, both actual fields, norm, nonsquares, degrees, separability, primitive generator and absolute polynomial irreducibility established above; their actual curve/model identifications remain separate.")),
            Paragraph(Text("E3.03 still requires actual smooth proper models, full constant fields, identification of their function fields and actual finite separable b-maps. E3.04 must identify the eight finite D-branch places and both infinity places with local rings, uniformizers, ramification and different hypotheses. E3.05 must apply Riemann–Hurwitz on that quotient model to obtain 2g(H)−2 = 2(−2)+8 = 4 and genus three. Squarefree degree eight alone is not that model-level proof.")),
            Paragraph(Text("E3.09 still requires nine actual simple f-zero places above roots of N, with regularity of both conjugate factors, a nonzero companion and order one. E3.10 must identify both H-places over 1/3, proving q and f have order −1 at one and that the other has q regular and f nonzero, with the local norm/order bridge. E3.11 must supply the two actual infinity points and coordinates giving ord(q) = −3 and ord(f) = −4 at each. E3.12 must exclude all other odd valuations, discharge local Kummer parity and tame different hypotheses, and prove exactly ten branches. The rational-field simple pole above is not a substitute for these local assertions.")),
            Paragraph(Text("E3.13 still requires the actual smooth projective normalization, its full constants and model morphism, and matched Riemann–Hurwitz with 2g(X)−2 = 2(2·3−2)+10 = 18, giving geometric genus ten. Arithmetic genus fifteen is not substituted. For E3.14 the elementary all-integer finiteness application in the following section already supplies finiteness of G(a,b) = 0, including A(b) ≠ 0 on integer b and finite a-fibers; this algebra section does not erase or reprove that result. The separate geometric route still owes an actual integer map to the constructed smooth affine quotient, its at-most-two fibers, and a Siegel or complete hyperelliptic finiteness theorem with all hypotheses matched. The F1–F3, G1–G5, E1–E4 and original 21+5 obligations are unchanged. No complete E3, effective point list, emptiness or graph classification follows from the algebra application alone."))));
    }

    private static DocumentBlock IntegerFiniteness()
    {
        Formula b=V("b"),u=V("u"),r=V("r"),t=V("t"),q=V("q"),a=V("A"),bb=V("B"),c=V("C");
        Formula d0=new Formula.Subscript(V("D"),Num(0)),tr=new Formula.Subscript(V("T"),r);
        Formula l0=new Formula.Subscript(V("L"),Num(0)),m0=new Formula.Subscript(V("M"),Num(0));
        Formula lr=new Formula.Subscript(V("L"),r),mr=new Formula.Subscript(V("M"),r),hr=new Formula.Subscript(V("H"),r);
        Formula f=Call("F",u,b),g=Call("G",u,b),qq=V("Q");
        return new DocumentBlock.Section(H("Integer points on the endpoint equality polynomial"),Blocks(
            Paragraph(Text("The equality-curve remark in paper/sections/endpoint-one-spectrum.tex, label rem:endpoint-one-equality-curve, at the same public revision b93becea662a746badeadba42fdc3d3eb3db9382 supplies the polynomial below. The scalar C in this section denotes its constant term in q, distinct from the quotient matrix above. We give an elementary arithmetic derivation of finiteness by applying the existing facts that a nonzero polynomial over the integers has finitely many roots, a finite union of finite sets is finite, and a set with finite projection and finite fibers is finite. These are supplied by Polynomial.finite_setOfPred_isRoot, Set.Finite.biUnion and Set.Finite.of_finite_fibers. The parameter domain is all integer pairs (a,b), with no positivity or spectral-ordering assumption.")),
            Equation(t,Mul(b,Add(b,Num(2)))),
            Equation(q,Mul(V("a"),Sub(t,V("a")))),
            Equation(a,Sub(Mul(Num(3),b),Num(1))),
            Equation(bb,Mul(b,Sub(Add(Pow(b,2),Mul(Num(4),b)),Num(1)))),
            Equation(c,Negate(Mul(Mul(Sub(Add(Pow(b,2),Mul(Num(2),b)),Num(1)),Sub(Add(Pow(b,2),Mul(Num(3),b)),Num(1))),Sub(Sum(Pow(b,3),Mul(Num(3),Pow(b,2)),Mul(Num(3),b)),Num(1))))),
            Equation(Call("G",V("a"),b),Sum(Mul(a,Pow(q,2)),Mul(bb,q),c)),
            Paragraph(Text("Let n=|b| be at least four. The triangle inequality gives |A|≥2n and |B|≤3n³. The three factors in |C| are bounded respectively by 2n², 2n² and 3n³, so |C|≤18n⁷. If G(a,b)=0 and x=|q|, then 2nx²≤3n³x+18n⁷. Were x>4n³, we would have 24n³x<6nx² and 144n⁷<9nx². Multiplying the preceding weak inequality by eight would then give 16nx²<15nx², a contradiction. Thus |q|≤4n³.")),
            Paragraph(Text("The involution a↦t−a preserves q and G. Choose u from a and t−a with |u|≤|t−u|, and put v=t−u. Since |b+2|≥n−2 and n≥4, n²≤2|t|≤2(|u|+|v|)≤4|v|. Multiplication by |u|, together with |uv|=|q|≤4n³, gives |u|n²≤16n³, hence |u|≤16n. The chosen pair (u,b) is still a solution. This choice preserves b and works for both signs of b; it is used only to bound the projection, so both original involution partners remain in the final set.")),
            Paragraph(Text("In the following identities write q=u(t−u). Define the auxiliary integer F and the following polynomials. All displayed polynomial identities hold over the integers without division.")),
            Equation(f,Sub(Sub(Sub(Mul(Num(9),Pow(u,2)),Mul(Num(3),u)),Mul(Num(3),Pow(b,2))),Mul(Num(13),b))),
            Equation(qq,Sum(Mul(Sub(Mul(Num(27),b),Num(9)),Pow(u,2)),Mul(Sum(Mul(Negate(Num(54)),Pow(b,3)),Mul(Negate(Num(90)),Pow(b,2)),Mul(Num(45),b),Negate(Num(3))),u),Mul(Num(27),Pow(b,5)),Mul(Num(99),Pow(b,4)),Mul(Num(54),Pow(b,3)),Mul(Negate(Num(66)),Pow(b,2)),Mul(Num(11),b),Negate(Num(1)))),
            Equation(l0,Mul(Mul(Num(3),Sub(Add(Mul(Num(3),Pow(b,2)),Mul(Num(6),b)),Num(1))),Sum(Mul(Negate(Num(21)),Pow(b,2)),Mul(Num(8),b),Num(1)))),
            Equation(m0,Sum(Mul(Negate(Num(333)),Pow(b,5)),Mul(Negate(Num(1197)),Pow(b,4)),Mul(Negate(Num(258)),Pow(b,3)),Mul(Num(1436),Pow(b,2)),Mul(Negate(Num(661)),b),Num(81))),
            Equation(Mul(Num(81),g),Sum(Mul(f,qq),Mul(u,l0),m0)),
            Paragraph(Text("For n≥1 and |u|≤16n, summing absolute monomials and using nʲ≤nᵏ for j≤k gives |Q−27b⁵|≤12519n⁴, |L₀|≤900n⁴ and |M₀|≤3966n⁵. The first constant is 36·256+192·16+231=12519; the second is 3·10·30=900; the third is 333+1197+258+1436+661+81=3966. For n≥1000, 12519n⁴≤26n⁵, and hence |Q|≥27n⁵−12519n⁴≥n⁵. On a solution the identity gives |F|n⁵≤|FQ|=|uL₀+M₀|≤(16·900+3966)n⁵=18366n⁵. Cancelling the positive n⁵ yields |F(u,b)|≤18366. Thus every solution with |b|≥1000 has a representative with the same b and an integer r=F(u,b) in [−18366,18366].")),
            Paragraph(Text("For each fixed integer r, define the following polynomials in b. Here A, B and C retain their definitions above.")),
            Equation(d0,Sub(Add(Mul(Num(3),Pow(b,2)),Mul(Num(6),b)),Num(1))),
            Equation(tr,Sum(Mul(Num(3),Pow(b,2)),Mul(Num(13),b),r)),
            Equation(lr,Mul(Mul(Num(3),d0),Sum(Mul(a,d0),Mul(Negate(Num(2)),Mul(a,tr)),Mul(Num(9),bb)))),
            Equation(mr,Sum(Mul(Mul(a,tr),Add(Pow(d0,2),tr)),Mul(Negate(Num(9)),Mul(bb,tr)),Mul(Num(81),c))),
            Paragraph(Text("When F(u,b)=r, the identities 9q=3uD₀−Tᵣ and 9u²=3u+Tᵣ reduce 81G(u,b) to uLᵣ+Mᵣ. For a solution Mᵣ=−uLᵣ, so the eliminant below vanishes. No division by Lᵣ occurs, including when Lᵣ=0.")),
            Equation(hr,Sub(Add(Mul(Num(9),Pow(mr,2)),Mul(Num(3),Mul(mr,lr))),Mul(tr,Pow(lr,2)))),
            Equation(hr,Mul(Sub(Sub(Mul(Num(9),Pow(u,2)),Mul(Num(3),u)),tr),Pow(lr,2))),
            Paragraph(Text("The second equality holds under the two equations F(u,b)=r and G(u,b)=0; its right side is zero. Expanding the defining polynomials gives:")),
            Equation(lr,Sum(Mul(Negate(Num(189)),Pow(b,4)),Mul(Sub(Negate(Num(306)),Mul(Num(54),r)),Pow(b,3)),Mul(Sub(Num(216),Mul(Num(90),r)),Pow(b,2)),Mul(Sub(Mul(Num(54),r),Num(6)),b),Negate(Num(3)),Mul(Negate(Num(6)),r))),
            Equation(mr,Sum(Mul(Sub(Mul(Num(27),r),Num(333)),Pow(b,5)),Mul(Sub(Mul(Num(99),r),Num(1197)),Pow(b,4)),Mul(Sub(Mul(Num(63),r),Num(258)),Pow(b,3)),Mul(Sub(Num(1436),Mul(Num(30),r)),Pow(b,2)),Mul(Sum(Mul(Num(3),Pow(r,2)),Mul(Negate(Num(2)),r),Negate(Num(661))),b),Num(81),Negate(Pow(r,2)),Negate(r))),
            Paragraph(Text("These expansions show that Hᵣ has degree at most ten. Its coefficient of b¹⁰ is 9(27r−333)²−3·189²=729((3r−37)²−147). For any integer r, (3r−37)² is congruent to one modulo three, whereas 147 is congruent to zero. The coefficient is therefore nonzero. Hᵣ is a nonzero polynomial of degree exactly ten and has finitely many integer roots.")),
            Paragraph(Text("The b-projection of G(a,b)=0 is contained in [−999,999] together with the union of the root sets of Hᵣ for integers r in [−18366,18366]. Both intervals are finite, and each root set is finite, so the projection is finite. For every fixed integer b, the polynomial G(a,b) in a has quartic coefficient 3b−1. It is nonzero because 3b=1 has no integer solution; its integer root set, and hence each a-fiber, is finite. Applying finiteness from finite projection and finite fibers proves that the set of all (a,b) in ℤ² with G(a,b)=0 is finite. This includes zero and negative coordinates, every small-b fiber, and both involution partners.")),
            Paragraph(Text("This application establishes finiteness of the stated polynomial zero set. An effective list of points, emptiness and classification require further arguments. Relating the polynomial to admissible graph or matrix parameters is a separate mathematical step. The arithmetic argument does not establish geometric irreducibility, Kummer models, full constant fields or separability, local orders or ramification, or genus-three and genus-ten calculations. The public source's geometric discussion is separate from the polynomial and elementary finiteness argument given here."))));
    }

    private static Formula Sum(params Formula[] terms) => terms.Aggregate(Add);
    private static DocumentBlock Equation(Formula left,Formula right) => new DocumentBlock.DisplayFormula(Eq(left,right));

    private static DocumentBlock Node(string id,string title,string name,Formula f,string text,DescribeRole role,AssessedProvenance? provenance = null) =>
        Describe.Lean(DescribeId.Create("six-"+id),DeclarationHandle.Create(Prefix+name),H(title),
            StatementSource.FromAuthor(Disp(f)),provenance ?? AssessedProvenance.FromLiterature(Source),Blocks(Paragraph(Text(text))),role);
